t.script:
function initLuwaPad(canvasId, inputId) {
    var canvas = document.getElementById(canvasId);
    var input = document.getElementById(inputId);
    if (!canvas || !input) return;
    var ctx = canvas.getContext('2d');
    ctx.strokeStyle = '#0f172a';
    ctx.lineWidth = 2.2;
    ctx.lineCap = 'round';
    var drawing = false;
    var dirty = false;

    function getPos(e) {
        var rect = canvas.getBoundingClientRect();
        var clientX = e.touches ? e.touches[0].clientX : e.clientX;
        var clientY = e.touches ? e.touches[0].clientY : e.clientY;
        return {
            x: (clientX - rect.left) * (canvas.width / rect.width),
            y: (clientY - rect.top) * (canvas.height / rect.height)
        };
    }

    function start(e) {
        e.preventDefault();
        drawing = true;
        dirty = true;
        var pos = getPos(e);
        ctx.beginPath();
        ctx.moveTo(pos.x, pos.y);
    }

    function move(e) {
        if (!drawing) return;
        e.preventDefault();
        var pos = getPos(e);
        ctx.lineTo(pos.x, pos.y);
        ctx.stroke();
    }

    function stop() {
        if (!drawing) return;
        drawing = false;
        if (dirty) {
            input.value = canvas.toDataURL('image/png');
        }
    }

    canvas.addEventListener('mousedown', start);
    canvas.addEventListener('mousemove', move);
    window.addEventListener('mouseup', stop);
    canvas.addEventListener('touchstart', start, {passive: false});
    canvas.addEventListener('touchmove', move, {passive: false});
    canvas.addEventListener('touchend', stop);
}

function clearLuwaPad(canvasId, inputId) {
    var canvas = document.getElementById(canvasId);
    var input = document.getElementById(inputId);
    if (canvas) {
        var ctx = canvas.getContext('2d');
        ctx.clearRect(0, 0, canvas.width, canvas.height);
    }
    if (input) {
        input.value = '';
    }
}

document.addEventListener('DOMContentLoaded', function() {
    initLuwaPad('sig_canvas_luwa', 'sig_input_luwa');
    initLuwaPad('sig_canvas_tech', 'sig_input_tech');
    initLuwaPad('sig_canvas_hr', 'sig_input_hr');
    initLuwaPad('sig_canvas_fin', 'sig_input_fin');
    initLuwaPad('sig_canvas_ceo', 'sig_input_ceo');
});
